TYPE E_GateState
    (IDLE:=0, OPENING:=1, CLOSING:=2, FAULT:=3);
END_TYPE

FUNCTION_BLOCK FB
VAR_INPUT
    openBtn    : BOOL;
    closeBtn   : BOOL;
    openLimit  : BOOL;
    closeLimit : BOOL;
    obstacle   : BOOL;
END_VAR
VAR_OUTPUT
    motorUp   : BOOL;
    motorDown : BOOL;
    errorFlag : BOOL;
END_VAR
VAR
    state        : E_GateState := E_GateState.IDLE;
    prevOpenBtn  : BOOL := FALSE;
    prevCloseBtn : BOOL := FALSE;
    edgeOpen     : BOOL;
    edgeClose    : BOOL;
END_VAR

    edgeOpen  := openBtn AND NOT prevOpenBtn;
    edgeClose := closeBtn AND NOT prevCloseBtn;

    CASE state OF
        E_GateState.IDLE:
            motorUp   := FALSE;
            motorDown := FALSE;
            errorFlag := FALSE;
            IF edgeOpen AND NOT openLimit THEN
                state := E_GateState.OPENING;
            ELSIF edgeClose AND NOT closeLimit THEN
                state := E_GateState.CLOSING;
            END_IF

        E_GateState.OPENING:
            IF obstacle THEN
                motorUp   := FALSE;
                state     := E_GateState.FAULT;
            ELSE
                IF openLimit THEN
                    motorUp := FALSE;
                    state   := E_GateState.IDLE;
                ELSE
                    motorUp := TRUE;
                END_IF
            END_IF

        E_GateState.CLOSING:
            IF obstacle THEN
                motorDown := FALSE;
                state     := E_GateState.OPENING;
            ELSE
                IF closeLimit THEN
                    motorDown := FALSE;
                    state     := E_GateState.IDLE;
                ELSE
                    motorDown := TRUE;
                END_IF
            END_IF

        E_GateState.FAULT:
            motorUp   := FALSE;
            motorDown := FALSE;
            errorFlag := TRUE;
            IF openBtn AND closeBtn THEN
                errorFlag := FALSE;
                state     := E_GateState.IDLE;
            END_IF
    END_CASE

    prevOpenBtn  := openBtn;
    prevCloseBtn := closeBtn;
END_FUNCTION_BLOCK
